def main() -> int:
    """Send the embedded seed SQL to psql without requiring a Python DB driver."""
    psql = shutil.which("psql")
    if psql is None:
        print(
            "Could not find 'psql' on PATH. Install/use the PostgreSQL client, "
            "or run this script in an environment where psql is available.",
            file=sys.stderr,
        )
        return 1

    host = os.getenv("DB_HOST", "localhost")
    port = os.getenv("DB_PORT", "5432")
    dbname = os.getenv("DB_NAME", "responsematch")
    user = os.getenv("DB_USER", "rm_user")

    command = [
        psql,
        "-X",  # Ignore any local psqlrc customizations.
        "-h", host,
        "-p", port,
        "-U", user,
        "-d", dbname,
        "-v", "ON_ERROR_STOP=1",
    ]

    print(f"Connecting to PostgreSQL database '{dbname}' as '{user}'...")
    print("If prompted, enter the PostgreSQL password. It will not be shown.")

    try:
        # psql prompts securely for a password when needed. SQL is supplied on stdin.
        result = subprocess.run(command, input=SEED_SQL, text=True, check=False)
        if result.returncode != 0:
            print(
                "Seed script failed. psql reported an error; check the message above. "
                "Because the SQL runs in a transaction, failed inserts should be rolled back.",
                file=sys.stderr,
            )
            return result.returncode
        print(f"Synthetic seed data inserted successfully into database '{dbname}'.")
        return 0
    except OSError as exc:
        print(f"Could not run psql: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

